#!/usr/bin/env python3
"""Render the V6 module report from the measured, anonymized result file."""
from pathlib import Path
import html
import json
from datetime import datetime

ROOT = Path(__file__).resolve().parents[2]
OUT = ROOT / 'docs/proposition/analyse/v6'
r = json.loads((OUT / 'modules-resultats.json').read_text())
a = json.loads((ROOT / 'tools/music-engine-poc/results.json').read_text())
def esc(s): return html.escape(str(s))
def mib(n): return f'{n / 1048576:.2f}'.replace('.', ',')
def table(headers, rows):
    return '<div class="table-wrap"><table><thead><tr>'+''.join('<th>'+esc(x)+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(x)+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'

topology_rows = []
for case in r['topologies']:
    if case['case'] == 'disabled':
        topology_rows.append(['Désactivés', '0', '0', '0', '0', 'PASS'])
        continue
    metrics = case['resources']
    topology_rows.append([esc(case['case']),case['active_modules'],case['total_processes'],mib(sum(v['rss_peak_sampled_bytes'] for v in metrics.values()))+' Mio',f"{sum(v['cpu_percent_one_core'] for v in metrics.values()):.2f}".replace('.',',')+' %',case['status']])
master_rss = [x['before']['master_rss_bytes'] for x in r['master_tests'].values() if x.get('before',{}).get('master_rss_bytes')]
module_tests = r.get('checks',{}).get('module_tests',{}).get('tests_passed','À relire')
native_tests = r.get('checks',{}).get('native_model_tests',{}).get('tests_passed','À relire')
music = next(m for c in r['topologies'] if c['case']=='with-music' for g in c['groups'] for m in g['modules'] if m['kind']=='music')
base = next(c for c in r['topologies'] if c['case']=='merged')
modules = base['groups'][0]['modules']
module_rows = [[esc(m['module']), m['devices'],m['points'],m['observed_slots'],m['catalogue']['owned_capacity_bytes'],m['value_container_bytes'],esc(str(m['processing_mean_ns'])+' ns')] for m in modules]
master_rows = [[esc(name),esc(result['status']), 'Oui' if result.get('owned_children_gone') else '—'] for name,result in r['master_tests'].items()]
css = (OUT/'index.html').read_text().split('<style>',1)[1].split('</style>',1)[0]
page = '''<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>V6 · Modules Rust et master minimal</title><style>'''+css+'''
.flow{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin:18px 0}.flow>article{border:1px solid var(--line);padding:18px;border-radius:10px}.flow .wide{grid-column:1/-1;background:var(--soft)}.flow h3{margin:0 0 9px}.check{font-weight:700;color:var(--green)}@media(max-width:650px){.flow{grid-template-columns:1fr}.flow .wide{grid-column:auto}}
</style></head><body><div class="wrap" id="haut"><header class="hero"><p class="eyebrow">Moli · Complément V6 · 27 octobre 2026</p><h1>Un master séparé.<br>Des modules regroupables.</h1><p class="intro">Le prototype lance les modules choisis, partage les ressources d’un groupe et mesure chaque processus. Le décodage musical Rust est raccordé en MQTT sur une sortie muette. Les connexions physiques restent à intégrer.</p><div class="meta"><span>Rust 1.99.1 · release · deux tâches de compilation</span><span>Aucun ordre physique</span><span>Dernière campagne : '''+esc(datetime.fromisoformat(r['validated_at']).strftime('%d/%m/%Y à %H:%M UTC'))+'''</span></div></header>
<p class="note"><a href="index.html">Dossier V6</a> · <a href="charge.html">Charge de vingt maisons</a> · <a href="memoire-1g.html">Analyse mémoire sous 1 Gio</a> · <a href="modules-resultats.json">Mesures brutes</a> · <a href="modules-preuves.json">Preuves et empreintes</a></p>
<div class="layout"><nav class="toc" aria-label="Sommaire"><strong>Dans ce complément</strong><a href="#master">01 · Master</a><a href="#modules">02 · Modules</a><a href="#mesures">03 · Mémoire et CPU</a><a href="#contrat">04 · Contrat MQTT</a><a href="#musique">05 · Moteur musical</a><a href="#validation">06 · Tests et suites</a></nav><main class="main">
<section class="section" id="master"><div class="section-head"><h2>01 · Le master démarre en premier</h2><span class="badge validated">Prototype vérifié</span></div><p>Son port HTTP loopback est ouvert avant la planification et les enfants. Le master appelle un exécutable adjacent connu pour obtenir les IDs des groupes, puis lance le broker et les hôtes. Il surveille disponibilité de processus, heartbeat, RSS et CPU. Il reste séparé même lorsque tous les modules sont fusionnés.</p>
<div class="flow" role="group" aria-label="Architecture des processus"><article class="wide"><h3>1 · Master minimal · processus séparé</h3><p>HTTP GET /health et /status → plan → lancement → surveillance → arrêt des enfants.</p></article><article><h3>2 · Groupe confort</h3><p>TaHoma + Ariston + météo/soleil. Tas et connexion MQTT du processus partagés.</p></article><article><h3>3 · Groupe médias</h3><p>Apple TV + moteur musical local. Peut être séparé davantage au démarrage.</p></article><article class="wide"><h3>Transport MQTT entre groupes</h3><p>Broker dans un autre enfant ; en mode fusionné, broker et modules partagent le même enfant. Le master ne traite pas leurs états.</p></article></div>
<p><strong>Surface bornée :</strong> trois routes GET, aucun corps de requête, 16 connexions, en-têtes de 8 Kio et délai de 2 s. Ni API d’écriture, ni téléchargement de plugins, ni interface de commande. La configuration et le binaire adjacent restent des fichiers locaux de confiance.</p><div class="cards"><article class="card"><h3>Binaire master sur disque</h3><strong class="number">'''+mib(r['binaries']['master']['bytes'])+''' Mio</strong><p class="caption">Taille du fichier release ; ce n’est pas sa RAM.</p></article><article class="card"><h3>RSS master observée</h3><strong class="number">'''+mib(min(master_rss))+'–'+mib(max(master_rss))+''' Mio</strong><p class="caption">Échantillons du master seul pendant les essais ; aucune borne OS imposée.</p></article><article class="card"><h3>Code métier dans le master</h3><strong class="number">Absent</strong><p class="caption">Code séparé et recherche de symboles : Ariston, Overkiz, MQTT et codecs audio absents de cet exécutable.</p></article></div>
<p>Une configuration incorrecte ou un enfant mort laisse le HTTP du master disponible. SIGINT/SIGTERM annulent le démarrage, arrêtent et récoltent ses enfants. Ce lot ne remplace pas encore le démarrage de production de Moli ; un superviseur système doit aussi couvrir le master lui-même.</p></section>
<section class="section" id="modules"><h2>02 · Les modules sont sélectionnés au démarrage</h2><p>Un même module conserve ses identifiants d’appareils, points et topics lorsqu’il change de groupe. Le plan refuse les doubles propriétaires d’une même source, les affectations ambiguës et les modules actifs sans groupe. Un module désactivé ne construit pas son adaptateur.</p>
'''+table(['Mode','Répartition','Processus avec master · quatre modules'],[['Fusionné','Master + un enfant avec modules et broker','2'],['Par groupes','Master + broker + confort + médias','4'],['Isolé','Master + broker + quatre hôtes','6'],['Tous désactivés','Master seul ; aucun broker','1']])+'''
<div class="note">Un groupe est ici un <strong>processus</strong>, avec son tas et son allocateur. Ce POC ne crée pas de conteneur OCI, de sandbox ou de mémoire partagée entre processus. La mémoire commune dans un groupe est un tas ordinaire ; un IPC ou mmap pourra être ajouté après mesure du besoin.</div>
'''+table(['Adaptateur','Ce qui est exécuté et exposé','Ce qui reste à raccorder'],[['TaHoma','Modèle natif Overkiz ; états multicanaux ; ouvrir/fermer/stop/my selon capacités','Transport box ; pas de position RTS inventée'],['Ariston','Modèle natif ; 13 points ; mode manuel/programme converti en enum compacte','Authentification et transport cloud'],['Météo / soleil','14 conditions fictives + 24 points solaires : aubes, lever/coucher, crépuscules, angles, prochains événements','Fournisseur météo et horloge réelle ; précision solaire à confronter à un éphéméride'],['Apple TV','11 valeurs observables et deux points de commande ; source/application distinctes ; titre, artiste, album, durée et position','Transport Apple TV et raccord HA vivant'],['Musique','Décodage Rust de WAV locaux synthétiques vers NullSink ; sélection/état/position via MQTT','Fournisseurs musicaux, lecteurs physiques, DSP et synchronisation']])+'''
<p>Température et humidité sont toujours deux valeurs indépendantes. Un titre principal de carte ne supprime aucun canal secondaire. L’Apple TV préserve les champs absents d’un instantané partiel ; un null explicite signifie inconnu. Les noms d’applications et choix sont dans les catalogues froids. <a href="sources-solaire.md">Méthode et limites du soleil</a>.</p></section>
<section class="section" id="mesures"><h2>03 · Mesurer les processus et le coût logique des modules</h2><p>Le petit scénario comporte '''+str(base['initial_observed_points'])+''' valeurs observées et trois commandes simulées. Le cas musique ajoute huit valeurs observées et une commande. Les modes sont comparés à description et valeurs initiales identiques ; ce scénario est distinct de la charge de vingt maisons.</p>
'''+table(['Scénario','Modules','Processus du banc','Somme des pics RSS échantillonnés','CPU cumulé · un cœur','Résultat'],topology_rows)+'''
<p class="caption">Le banc de topologie comprend un parent broker/observateur, pas le master. Les nombres de processus diffèrent donc du tableau de démarrage. Les pics ne sont pas nécessairement simultanés ; leur somme n’est ni une mesure de pages physiques uniques ni une limite mémoire. Les mesures CPU reposent sur des compteurs ps par centième de seconde et une fenêtre de quelques secondes : 0,00 % peut signifier une activité sous leur résolution. Le coût des processus ps utilisés pour mesurer n’est pas compris ; il faudra mesurer la supervision elle-même sur la cible de déploiement.</p>
<h3>Inventaire logique dans le cas fusionné</h3>'''+table(['Module','Appareils','Points déclarés','Valeurs courantes','Tables enum · capacité en octets','Conteneurs Value · octets','Traitement moyen'],module_rows)+'''
<p class="caption">Les temps moyens incluent observation, validation, comparaison et sérialisation des deltas du module. Ils excluent le transport et ne sont pas des délais de réponse d’un appareil. Les conteneurs Value excluent les clés, index, métadonnées et annexes de texte. Les capacités de tables excluent les en-têtes d’allocateur et Arc. Aucune RSS par module n’est inventée dans un tas partagé.</p>
<h3>Optimisations présentes et limites</h3><p>Les tables enum sont compactes à la frontière ; l’état conserve un code numérique. Les descriptions sont transférées depuis l’adaptateur une fois. Les états sont comparés et publiés seulement lorsqu’ils changent, avec une sérialisation qui emprunte leur contenu. Un groupe partage sa connexion MQTT et son runtime ; les séparer augmente les ressources répétées, mais réduit le périmètre d’une panne.</p><p>Les textes courants, les dernières valeurs et les schémas de cet outil sont encore en mémoire. Il ne démontre pas encore la politique disque du serveur 1414, un layout inline de production, ni l’élimination des allocations JSON de l’ancien pont HA. Les 114 Mio et les buffers de l’analyse précédente restent attachés à leur campagne : aucun gain de ces nouvelles petites fixtures ne leur est soustrait.</p></section>
<section class="section" id="contrat"><h2>04 · Description retained, états différentiels et générations</h2><pre><code>moli-probe/module/&lt;id&gt;/config
moli-probe/module/&lt;id&gt;/state/&lt;PointId&gt;
moli-probe/module/&lt;id&gt;/availability
moli-probe/module/&lt;id&gt;/simulate
moli-probe/module/&lt;id&gt;/command-result</code></pre><p>Le catalogue indique code, valeur native, libellé et version. L’état transporte valeur, qualité, séquence, génération d’instance et révision de description. Un client attend la bonne description avant d’interpréter un code. Une nouvelle génération invalide les valeurs et la disponibilité de l’ancienne ; les observations arrivées avant la description attendent dans un tampon borné.</p><p>Les commandes d’essai sont non retained, à génération exacte, identité bornée, expiration maximale de cinq secondes et déduplication bornée. L’enveloppe est limitée à 1 024 octets, le corps natif à 256. Une surcharge avant admission est comptée et ne bloque pas la boucle réseau. Cela ne constitue pas encore le raccord à la garde du moteur de production.</p><p>Les textes libres sont acceptés jusqu’à 4 096 octets UTF-8 ; un dépassement est refusé, sans troncature. Cette borne est un contrat d’essai, pas la décision finale entre texte inline et annexe. Les grands catalogues musicaux devront être paginés et rester hors des états retained courants.</p><div class="note warn">Le master publie ici ses mesures par HTTP. Sa télémétrie complète n’est pas encore republiée sur MQTT. Une mort brutale est visible dans le master, mais les appareils nécessitent encore un bail de fraîcheur MQTT ; un heartbeat de processus ne prouve pas la fraîcheur de leurs données.</div></section>
<section class="section" id="musique"><h2>05 · Le premier chemin audio natif fonctionne</h2><p>Le moteur local fourni par l’agent Music est une bibliothèque Rust autonome. Son chemin vérifié est : catalogue de deux pistes synthétiques → file révisionnée → décodeur Rust → sortie Null ou WAV. Il se construit et se restaure à l’arrêt. Play/pause/resume/seek/stop et la fin de fichier sont testés.</p><div class="cards"><article class="card"><h3>Essai autonome Null / WAV</h3><strong class="number">'''+str(a['demo']['frames_per_output'])+''' frames</strong><p class="caption">48 kHz, stéréo ; contenu PCM et empreinte identiques entre les sorties ; WAV de 38 444 octets.</p></article><article class="card"><h3>Essai par MQTT</h3><strong class="number">'''+str(music['adapter']['rendered_frames'])+''' frames</strong><p class="caption">'''+str(music['adapter']['samples'])+''' échantillons effectivement décodés vers NullSink après play ; aucune sortie physique.</p></article><article class="card"><h3>File PCM bornée du moteur</h3><strong class="number">16 Kio</strong><p class="caption">4 slots au maximum ; consommateur lent sans avancement de lecture ni croissance sans borne.</p></article></div>
<p>Le PCM circule par blocs, jamais en JSON ni en MQTT. Le banc modulaire rend un bloc par tick d’essai ; il vérifie le raccord de contrôle et le décodage, pas la cadence audio temps réel. Le fichier WAV canonique PCM16 stéréo 48 kHz est le seul format qualifié dans ce T0 ; le FLAC reste refusé.</p><p><strong>La cible reste un moteur complet comparable fonctionnellement à Music Assistant.</strong> Bibliothèque durable, fournisseurs, flux autorisés, DSP, gapless, vrais Cast/AirPlay/Alexa et horloges multiroom restent à développer et à qualifier séparément. Le travail fournisseur/lecteurs de l’agent Music dans tools/music-poc est distinct ; il n’est pas présenté ici comme une sortie matérielle validée. <a href="../../../../tools/music-engine-poc/README.md">API et bornes du moteur</a>.</p></section>
<section class="section" id="validation"><h2>06 · Ce que les essais prouvent</h2><p><strong>'''+str(module_tests)+''' tests d’hôtes/master, '''+str(native_tests)+''' tests des bibliothèques métier et 21 tests du moteur musical</strong>, chacun dans son périmètre. Les suites réutilisent des contrats broker et enum : leurs nombres ne représentent pas autant de fonctions nouvelles. Fmt et Clippy stricts sont contrôlés par le banc.</p>
'''+table(['Essai du master','Résultat','Enfants récoltés'],master_rows)+'''
<p>Les cinq scénarios de topologie réussissent. Les trois modes actifs de base ont une empreinte sémantique initiale identique. L’essai isolé arrête uniquement son enfant Apple TV et conserve les autres groupes ainsi que la santé du master.</p><h3>Deux régressions reproduites puis corrigées</h3><ul><li>Un groupe de 32 modules météo bloquait l’initialisation MQTT : le test expirait après six secondes. Les notifications inutiles sont filtrées et la file d’admission ne bloque plus la boucle réseau ; le même test passe avec 1 216 valeurs.</li><li>Le changement de génération conservait des valeurs et une disponibilité de l’ancienne instance. Le test échouait sur la présence d’une ancienne valeur ; ces observations sont maintenant purgées avant le rejeu correspondant à la nouvelle description.</li></ul><h3>Étapes encore nécessaires</h3><p>Raccorder les transports réels derrière les codecs déjà réutilisés ; brancher les commandes sur le Hub et sa garde ; exposer la télémétrie complète en MQTT ; définir les baux de fraîcheur et le redémarrage contrôlé ; qualifier le démarrage système, les plafonds OS, la mémoire partagée éventuelle et Linux/musl. Ensuite rejouer une charge comparable sur les vraies descriptions, puis qualifier le moteur musical par sortie et fournisseur. Le serveur 1414 est indépendant de ces essais.</p><p><a href="../../../../tools/module-host-poc/README.md">Reproduire et configurer</a> · <a href="modules-resultats.json">Résultats</a> · <a href="modules-preuves.json">Empreintes des sources et résultats</a></p></section>
</main></div><footer class="footer">Rapport local autonome, sans bibliothèque distante, sans données d’une maison et sans commande physique. Les mesures décrivent ce prototype et cette cible de compilation.</footer></div></body></html>'''
(OUT/'modules.html').write_text(page)
print('Rapport V6 modules régénéré depuis les mesures.')
